    if(aT>.01){R.glass([XC-.7,yT,-.55],[1.4,0,0],[0,0,1.1],{c:P.c4,a:aT,nu:6,nv:4});
      R.label([XC+.7,yT,0],k===0?'types · checked by tsc':'types · erased',{fs:12.5,b:1,al:'left',dx:10,c:P.c4,a:aT,grp:'cmp'})}
